-- Spanish for the written library (Story/Library), part 2: dead phones' texts from the news (July 4-5), the owner's
-- own last day, and what kept coming after they died. The English line is the key. The owner's own lines ("self")
-- fit a man or a woman.
return {
    -- news -----------------------------------------------------------------------------------------------------
    ["[Turn on|Watch] channel 3. Louisville ER [overflowing|turning people away]. Kayla's bus [gets in|left] an hour ago."] = "[Pon|Mira] el canal 3. Urgencias de Louisville [desbordado|rechazando gente]. El autobús de Kayla [llega|salió] hace una hora.",
    ["heard [gunshots|sirens] down by the river after fireworks. [nobody's saying|radio's quiet] what happened"] = "se oyeron [disparos|sirenas] por el río después de los fuegos. [nadie dice|la radio no dice] q pasó",
    ["Gas station on 31W [lined up|out of regular]. [Fill the cans|Top the truck] now. Kayla still not home."] = "La gasolinera de la 31W [con fila|sin regular]. [Llena los bidones|Llena la camioneta] ya. Kayla todavía no llega.",
    ["Spiffo's [staying open|running low] for the shelter crowd. tammy says [bring water|ice machine died]"] = "Spiffo's [sigue abierto|ya casi no tiene nada] para la gente del refugio. tammy dice [traigan agua|se murió la máquina de hielo]",
    ["kayla texted: [stuck at the fence|turned back at 31W]. army [checking every car|not letting anyone through]. she's at [a gas station|the truck stop]"] = "kayla escribió: [atorada en la cerca|la regresaron en la 31W]. el ejército [revisa cada auto|no deja pasar a nadie]. está en [una gasolinera|la parada de camiones]",
    ["coach burris opened the school gym. [cots arriving|red cross here]. [bobby|he] went to help unload [instead of practice|with travis]"] = "el coach burris abrió el gimnasio de la escuela. [están llegando catres|llegó la cruz roja]. [bobby|él] fue a ayudar a descargar [en vez de entrenar|con travis]",
    ["missy at the motel says [rooms full|people paying cash]. [nobody checking out|keys left on the desk] since yesterday"] = "missy del motel dice [q no hay cuartos|q la gente paga en efectivo]. [nadie ha salido|dejan las llaves en el mostrador] desde ayer",
    ["Lumberyard [closing early|shutting down friday]. [bobby|the kid] got his check. owner said take care"] = "El aserradero [cierra temprano|cierra el viernes]. [bobby|el muchacho] ya recibió su cheque. el dueño dijo cuídense",
    ["heard gunshots near the lumberyard. [mr henderson|the old man] on elm still hasn't answered. [going to check|you go]?"] = "se oyeron disparos cerca del aserradero. [el sr henderson|el viejito] de la calle elm todavía no contesta. [voy a ver|vas tú]?",
    ["cell service spotty. [walkie talkies on channel 3|meet at the mailbox] at 7. [check on wilson|check the generator]."] = "la señal va y viene. [walkie talkies en el canal 3|nos vemos en el buzón] a las 7. [ve a ver a wilson|revisa el generador].",
    ["Parade starts at 10 on Main. [Bring chairs|Grab a spot by the bank] before it fills up"] = "El desfile empieza a las 10 en Main. [Trae sillas|Aparta un lugar junto al banco] antes de que se llene",
    ["fireworks at the river tonight. [meet at the ramp|park by spiffo's] around 8?"] = "fuegos artificiales en el río hoy. [nos vemos en la rampa|estaciónate junto a spiffo's] como a las 8?",
    ["Grill's hot. [Burgers|Brats] on in ten. [Your mother|Mom] made potato salad"] = "La parrilla ya está caliente. [Hamburguesas|Salchichas] en diez. [Tu mamá|Mamá] hizo ensalada de papa",
    ["Kayla just texted. Louisville ER is [packed|turning people away]. [Something bad|Weird] going on"] = "Kayla acaba de escribir. Urgencias de Louisville está [llena|rechazando gente]. [Algo malo|Algo raro] está pasando",
    ["heard a guy bit a paramedic at the fairgrounds. [for real|swear to god]. dad says dont go near the river"] = "dicen q un tipo mordió a un paramédico en la feria. [en serio|te lo juro]. papá dice q no vayamos al río",
    ["all circuits busy when i tried kayla. [tried 3 times|kept getting the recording]. [u get through|any luck]?"] = "todos los circuitos ocupados cuando le marqué a kayla. [lo intenté 3 veces|me salía la grabación]. [tú pudiste|tuviste suerte]?",
    ["Pastor Glen said the church basement opens tomorrow. [Just in case|For anyone]. [Come by|We'll go] after lunch"] = "El pastor Glen dijo que mañana abren el sótano de la iglesia. [Por si acaso|Para quien sea]. [Ven|Vamos] después de comer",
    ["Radio says 31W backup at the bridge. [Take 60|Cut through Muldraugh] if you're coming from town"] = "La radio dice que hay fila en la 31W en el puente. [Toma la 60|Corta por Muldraugh] si vienes del pueblo",
    ["Dispatch says [multiple 10-31s|radio's blowing up] in Louisville. [Stand by|Gear up] at {jobPlace}"] = "Despacho dice [varios 10-31|la radio no para] en Louisville. [Estén atentos|Prepárense] en {jobPlace}",
    ["twiggy's packed already. jimmy says [keg's tapped|taps are dry] by noon. [get here|hurry up]"] = "twiggy's ya está lleno. jimmy dice q [el barril se acaba|no queda cerveza] al mediodía. [vente|apúrate]",
    ["Grace's party at the club ended [early|before dark]. [Something happened|People left fast]. [Did u hear|Know why]?"] = "La fiesta de Grace en el club terminó [temprano|antes de oscurecer]. [Algo pasó|La gente se fue rápido]. [¿Supiste algo?|¿Sabes por qué?]",
    ["bobby took off on his board toward the river. [hasnt texted back|phone's off]. [mom's freaking|dad's yelling]"] = "bobby se fue en su patineta hacia el río. [no ha contestado|tiene el teléfono apagado]. [mamá está histérica|papá está gritando]",
    ["Earl says the cattle been [lowing all morning|acting strange] at the Brott farm. [Never seen it|Not like this]"] = "Earl dice que el ganado del rancho Brott [ha estado mugiendo toda la mañana|se está portando raro]. [Nunca lo había visto|No así]",
    ["saw army trucks rolling north on 31W past the speedway. [covered backs|canvas tops]. [where they going|what's that about]"] = "vi camiones del ejército yendo al norte por la 31W pasando el autódromo. [con la caja tapada|con lona]. [a dónde irán|q será eso]",
    ["IGA sold out of [water|ice|charcoal] by 9. [Truck's not coming|Next delivery's tuesday] they say"] = "El IGA se quedó sin [agua|hielo|carbón] a las 9. [El camión no va a venir|La próxima entrega es el martes], dicen",
    ["Lonnie's rig stuck at the checkpoint. [Says soldiers|Guys in camo] won't let him turn around. [Full load|Produce]'ll rot"] = "El tráiler de Lonnie está atorado en el retén. [Dice que los soldados|Unos tipos de camuflaje] no lo dejan dar la vuelta. [La carga|La verdura] se va a pudrir",
    ["Dr. Sato texted Trish: [Don't come in|Stay home] if you can. [It's bad|Worse than they say] at the hospital"] = "Dr. Sato le escribió a Trish: [No vengas|Quédate en casa] si puedes. [Está feo|Peor de lo que dicen] en el hospital",
    ["missy at the motel says [rooms full|people sleeping in the lobby]. [paid cash|didnt give names]. [weird|creepy]"] = "missy del motel dice [q no hay cuartos|q hay gente durmiendo en el vestíbulo]. [pagaron en efectivo|no dieron nombres]. [raro|da miedo]",
    ["Shirley's neighbor answered her phone. [Said she's resting|Wouldnt say where she went]. [Call again|Try later]"] = "El vecino de Shirley contestó su teléfono. [Dijo que está descansando|No quiso decir a dónde fue]. [Llama otra vez|Intenta más tarde]",
    ["grace's party at west maple ended [before the fireworks|right after the sirens]. [ambulances|police] came up the drive"] = "la fiesta de grace en west maple terminó [antes de los fuegos|justo después de las sirenas]. [ambulancias|la policía] subieron por la entrada",
    ["iga cash only now. [line wraps the block|out of carts again]. [get there early|bring exact change]"] = "en el iga ahora solo efectivo. [la fila da la vuelta a la cuadra|ya no hay carritos otra vez]. [llega temprano|lleva el cambio exacto]",
    ["Water truck at the [fire station|courthouse] by noon. [Fill every jug|Bring the big cooler]. [Your dad|Uncle Roy] went at 6"] = "La pipa de agua llega a [la estación de bomberos|el juzgado] al mediodía. [Llena todos los garrafones|Trae la hielera grande]. [Tu papá|El tío Roy] fue a las 6",
    ["Store on [Main|Maple] got hit last night. [Front glass|Back door] smashed. Nothing taken. Deputy Lusk took the report"] = "Anoche se metieron a la tienda de [Main|Maple]. [El vidrio de enfrente|La puerta de atrás] destrozado. No se llevaron nada. El alguacil Lusk hizo el reporte",
    ["Curfew starts [9|10] tonight. [Deputy said|Sheriff said] nobody on the streets after. [Stay put|Get home before dark]"] = "El toque de queda empieza a las [9|10] esta noche. [El alguacil dijo|El sheriff dijo] que nadie en la calle después. [No te muevas|Llega a casa antes de oscurecer]",
    ["Heard [shots|something] on [Elm|Oak] around 2 am. Dog quit barking. Dont go look"] = "Oí [disparos|algo] en [Elm|Oak] como a las 2 am. El perro dejó de ladrar. No vayas a ver",
    ["News says banks [closing early|limiting withdrawals] tomorrow. [Get cash today|Fill the bathtub with water too]"] = "Las noticias dicen que mañana los bancos [cierran temprano|limitan los retiros]. [Saca efectivo hoy|Llena también la tina de agua]",
    ["radio said [the fed|the governor] froze prices on gas and food. [rent too|not rent tho]"] = "la radio dijo q [el gobierno federal|el gobernador] congeló los precios de la gasolina y la comida. [la renta también|la renta no]",
    ["Courthouse [closed|running on emergency staff] starting monday. [All hearings pushed|Your date might move again]"] = "El juzgado [cierra|trabaja con personal de emergencia] desde el lunes. [Se aplazan todas las audiencias|Tu fecha se puede volver a mover]",
    ["Repo companies [told to stop|aint running] by the sheriff. [For now|Till the guard leaves]"] = "El sheriff [les ordenó parar|ya no deja trabajar] a los de embargos. [Por ahora|Hasta que se vaya la guardia]",
    ["lottery drawing [tonight|tomorrow] still on. [TV said so|Jimmy at twiggys said so]"] = "el sorteo de la lotería [de hoy|de mañana] sigue en pie. [lo dijeron en la tele|lo dijo jimmy en twiggys]",
    ["Landlord [cant evict|wont evict] under the emergency order. [Saw it on channel 3|Pastor Glen read it at church]"] = "Con la orden de emergencia el casero [no puede desalojarnos|no va a desalojarnos]. [Lo vi en el canal 3|El pastor Glen lo leyó en la iglesia]",
    ["Your [brother|sister] called. [Said|Says] the IGA on dixie highway is cleaned out. [Water|Canned goods|Batteries] gone"] = "Llamó tu [hermano|hermana]. [Dijo|Dice] que vaciaron el IGA de dixie highway. Ya no hay [agua|latas|pilas]",
    ["heard [gunshots|sirens] down by the [river|plant] around 2 am. u awake"] = "se oyeron [disparos|sirenas] por [el río|la planta] como a las 2 am. no duermes?",
    ["kayla says [they're not letting|nobody crosses] the [bridge|checkpoint] anymore. [stuck in louisville|turned around at the river]"] = "kayla dice q [ya no dejan pasar|ya nadie cruza] [el puente|el retén]. [atorada en louisville|la regresaron en el río]",
    ["Pastor Glen opened the [church|basement] at [first baptist|rosewood]. Your mother wants us there by dark. Bring the flashlight"] = "El pastor Glen abrió [la iglesia|el sótano] en [first baptist|rosewood]. Tu mamá quiere que estemos ahí antes de oscurecer. Trae la linterna",
    ["[Turn on|Watch] the news. Call me [when you see it|right now]"] = "[Pon|Mira] las noticias. Llámame [cuando lo veas|ahora mismo]",
    ["[kroger on dixie|the IGA] is out of water. [get some|fill the tub] tonight"] = "[el kroger de dixie|el IGA] ya no tiene agua. [consigue|llena la tina] esta noche",
    ["All leave canceled. Report to {jobPlace} [by 0600|ASAP]. Bring a bag"] = "Se cancelan los permisos. Preséntate en {jobPlace} [antes de las 0600|lo antes posible]. Trae una maleta",
    ["Pastor Glen opened the church [for anybody who needs it|to folks]. Your mother wants us there [tonight|by dark]"] = "El pastor Glen abrió la iglesia [para quien lo necesite|a la gente]. Tu mamá quiere que estemos ahí [esta noche|antes de oscurecer]",
    ["cant get through to anybody. all circuits busy. [text me|page me] when u get this"] = "no puedo comunicarme con nadie. todos los circuitos ocupados. [escríbeme|mándame al bíper] cuando veas esto",
    ["Dispatch says every car is holding at the station. [Something big|Don't ask me what]"] = "Despacho dice que todas las patrullas esperan en la estación. [Algo grande|No me preguntes qué]",
    ["Pastor Glen opened the church basement to anybody. [Cots|Food] coming from the IGA"] = "El pastor Glen abrió el sótano de la iglesia para todos. [Los catres|La comida] vienen del IGA",
    ["[Full|Modified] lockdown. Nobody in or out until further notice. Do not come to the front gate"] = "Encierro [total|parcial]. Nadie entra ni sale hasta nuevo aviso. No vengan a la puerta principal",
    ["Wade texted [10-7|can't talk] from Main. I could hear sirens. Lock up please"] = "Wade escribió [10-7|no puedo hablar] desde Main. Se oían sirenas. Cierra con llave por favor",
    ["courthouse locked down. june says [state police|men in suits] took boxes out of records"] = "cerraron el juzgado. june dice q [la policía estatal|unos tipos de traje] sacaron cajas del archivo",
    ["Dispatch took [fifty|sixty] calls in an hour. [One person|Dee] on the console. One"] = "Despacho recibió [cincuenta|sesenta] llamadas en una hora. [Una persona|Dee] en la consola. Una",
    ["The fire station siren is going steady, not on and off. I've never heard it do that"] = "La sirena de los bomberos suena sin parar, no a ratos. Nunca la había oído así",
    ["The prayer chain hasn't stopped [calling|ringing]. I can't write the names down fast enough"] = "La cadena de oración no ha dejado de [llamar|sonar]. No alcanzo a anotar los nombres",
    ["Channel 3 says the Louisville hospital is [turning people away|full]. [Call me|Text me back] when you see it"] = "En el canal 3 dicen que el hospital de Louisville [está rechazando gente|está lleno]. [Llámame|Contéstame] cuando lo veas",
    ["IGA is out of [water|ice]. [go now|get there] before the line wraps the building"] = "El IGA ya no tiene [agua|hielo]. [ve ya|llega] antes de q la fila le dé la vuelta al edificio",
    ["town hall is a shelter now. cots in the gym. marla dropped off [pallets|a truckload] of water"] = "la alcaldía ahora es refugio. catres en el gimnasio. marla dejó [tarimas|una camioneta llena] de agua",
    ["Army trucks on 31W by the bridge. They're stopping every car. Your mother says [don't go near it|stay home]"] = "Camiones del Ejército en la 31W junto al puente. Están parando cada auto. Tu mamá dice [que no te acerques|que te quedes en casa]",
    ["jimmy closed twiggys early. said [dont come tonight|somethings wrong]. first time in 12 years"] = "jimmy cerró twiggys temprano. dijo [no vengan hoy|algo anda mal]. primera vez en 12 años",
    ["marla's phone goes straight to voicemail. her cabin people are [waiting at|knocking on] the office door"] = "el teléfono de marla se va directo al buzón. la gente de las cabañas está [esperando en|tocando] la puerta de la oficina",
    ["The club is serving meals to anybody who comes. Grace is [running the kitchen|in charge, God help us]"] = "El club le está dando de comer a quien llegue. Grace [está a cargo de la cocina|manda, que Dios nos ayude]",
    ["The news says stay home. Your father says the news says a lot of things. [He's at the hardware store|He went to get gas]"] = "Las noticias dicen que nos quedemos en casa. Tu papá dice que las noticias dicen muchas cosas. [Está en la ferretería|Fue por gasolina]",
    ["Gas station on [Dixie|the highway] is out. Don't drive anywhere you don't have to"] = "La gasolinera de [Dixie|la carretera] se quedó sin nada. No manejes a ningún lado si no hace falta",
    ["The Clarks next door left [this morning|at dawn]. Didn't say goodbye. Their sprinkler's still running"] = "Los Clark de al lado se fueron [esta mañana|al amanecer]. No se despidieron. Su aspersor sigue prendido",
    ["trish says third floor is [full|doubling up]. beds in the hallway now"] = "trish dice q el tercer piso está [lleno|con dos por cuarto]. ahora hay camas en el pasillo",
    ["Ambulance diversion is on. Bring patients to the loading dock. Badge only"] = "Se están desviando las ambulancias. Traigan a los pacientes al andén de carga. Solo con credencial",
    ["News says every hospital in Louisville is turning ambulances away. [Stay at {jobPlace}|Sleep there] if you can"] = "Las noticias dicen que todos los hospitales de Louisville están rechazando ambulancias. [Quédate en {jobPlace}|Duerme ahí] si puedes",
    ["Do not transport [bite|fever] calls without a supervisor. That comes from the top"] = "No trasladen casos de [mordida|fiebre] sin un supervisor. La orden viene de arriba",
    ["ER goes to secure mode at [10|midnight]. Badge only at every door. No visitors. None"] = "Urgencias entra en modo seguro a las [10|doce]. Solo con credencial en todas las puertas. Sin visitas. Ninguna",
    ["kayla's stuck at her dorm. guard on the ramp wont let anybody drive out"] = "kayla está atorada en su dormitorio. la guardia en la rampa no deja salir a nadie en auto",
    ["There's a refrigerated truck at the service drive now. Don't ask about it. Nobody's asking"] = "Ahora hay un camión refrigerado en la entrada de servicio. No pregunten. Nadie está preguntando",
    ["The doctor down the street slept at the hospital [again|three nights now]. Her husband says she won't come home"] = "La doctora de la calle durmió en el hospital [otra vez|ya van tres noches]. Su esposo dice que no quiere volver a casa",
    ["Radio says the Army has the bridges. Nobody [in or out|crosses] after 11. Your dad went for [water|canned goods]"] = "La radio dice que el Ejército tiene los puentes. Nadie [entra ni sale|cruza] después de las 11. Tu papá fue por [agua|latas]",
    ["saw army trucks on dixie hwy by the plant. guys in camo putting up wire. [for real|this is real]"] = "vi camiones del ejército en la dixie hwy junto a la planta. tipos de camuflaje poniendo alambre. [en serio|esto es real]",
    ["Radio says 31W is closed at the [river bridge|county line]. They're turning everybody around"] = "La radio dice que cerraron la 31W en [el puente del río|la línea del condado]. Están regresando a todos",
    ["trucker on the cb says his [produce|meat] load is going bad. they wont let him run the reefer"] = "un camionero en el cb dice q su carga de [verdura|carne] se está echando a perder. no lo dejan prender el refrigerador",
    ["Soldier at the roadblock turned back a man with [oxygen tanks|insulin] in his trunk. No exceptions he said"] = "El soldado del retén regresó a un hombre con [tanques de oxígeno|insulina] en la cajuela. Sin excepciones, dijo",
    ["News helicopter over the backup. They said [3|5] miles of taillights. [Don't even try|Take the back way]"] = "Un helicóptero de las noticias sobre la fila. Dijeron [3|5] millas de autos. [Ni lo intentes|Ve por atrás]",
    ["Two units stuck in the line on the interstate. [Take the frontage road|Go around]. Do not wait"] = "Dos unidades atoradas en la fila de la interestatal. [Tomen la lateral|Rodeen]. No esperen",
    ["The church opened the fellowship hall for people stuck on the road. [Coffee and sandwiches|Cots]. Send them there"] = "La iglesia abrió el salón comunitario para la gente atorada en la carretera. [Café y sándwiches|Catres]. Mándalos para allá",
    ["All hands meeting at 6am. [Everybody|No exceptions]. It's about what's on the news"] = "Junta general a las 6am. [Todos|Sin excepciones]. Es por lo de las noticias",
    ["tv in the break room says louisville hospital is [full|overrun]. foreman turned it off"] = "la tele de la sala de descanso dice q el hospital de louisville está [lleno|desbordado]. el capataz la apagó",
    ["Radio says the Guard is moving down 31W. They might shut the plant. Nobody knows anything"] = "La radio dice que la Guardia viene bajando por la 31W. Quizá cierren la planta. Nadie sabe nada",
    ["guy from day shift didnt show. [wife's|kid's] sick they say. nobody asked questions"] = "el del turno de día no vino. dicen q [su esposa|su hijo] está enfermo. nadie preguntó nada",
    ["doug says army trucks are parked at the steelworks gate. [nobody in|nobody out] he thinks"] = "doug dice q hay camiones del ejército en la reja de la acería. cree q [no entra nadie|no sale nadie]",
    ["Earl says the Louisville channels are going quiet on the CB. One by one. He said pray"] = "Earl dice que los canales de Louisville se están quedando callados en el CB. Uno por uno. Dijo que recemos",
    ["Hank won't sell to anybody he doesn't know. [Cash on the counter|Back door only]. Period"] = "Hank no le vende a nadie que no conozca. [Efectivo en el mostrador|Solo por la puerta de atrás]. Punto",
    ["Feed store is limiting corn to [two|five] bags. Line's around the building"] = "La tienda de forraje solo vende [dos|cinco] bultos de maíz por persona. La fila le da la vuelta al edificio",
    ["the Brott cattle broke the north fence onto 31W. deputies came out. [gone by dawn|wouldnt say why]"] = "el ganado de Brott rompió la cerca del norte y salió a la 31W. vinieron los alguaciles. [para el amanecer ya no estaban|no quisieron decir por q]",
    ["The speedway gates are chained. Wendell called off the race. First time in thirty years"] = "Las rejas del autódromo tienen cadena. Wendell canceló la carrera. Primera vez en treinta años",
    ["Hank put plywood on the gun store windows and painted something on the door. [Won't say what|Couldn't read it]"] = "Hank tapó con madera las ventanas de la armería y pintó algo en la puerta. [No dice qué|No se pudo leer]",
    ["becky says her mom [has a bad fever|cant breathe right]. the ER in louisville wont take her"] = "becky dice q su mamá [tiene mucha fiebre|no puede respirar bien]. urgencias de louisville no la recibe",
    ["guy at the gas station bit the cashier. [cops came|ambulance came]. nobody knows whats going on"] = "un tipo en la gasolinera mordió a la cajera. [vino la policía|vino la ambulancia]. nadie sabe q está pasando",
    ["National Guard is setting up at the [armory|fairgrounds]. Stay off 31W"] = "La Guardia Nacional se está instalando en [la armería|la feria]. No tomes la 31W",
    ["Mall closing early. Corporate's orders. Call before you come in tomorrow"] = "El centro comercial cierra temprano. Órdenes de la empresa. Llama antes de venir mañana",
    ["heard [gunshots|fireworks] by the [mall|river] just now. dad got the shotgun out of the closet"] = "se acaban de oír [disparos|cohetes] por [el centro comercial|el río]. papá sacó la escopeta del clóset",
    ["my mom's filling the tub with water. canned food everywhere. she wont say why"] = "mi mamá está llenando la tina de agua. latas por todos lados. no quiere decir por q",
    ["star-e-plex cancelled every show. sign on the door. [weirdest 4th ever|manager just left]"] = "el star-e-plex canceló todas las funciones. letrero en la puerta. [el 4 de julio más raro de la vida|el gerente se fue nada más]",
    ["Rev. Lois opened the pantry to anybody. Line's at the side door. [Bring bags|Come early]"] = "La Rev. Lois abrió el banco de comida para todos. La fila está en la puerta lateral. [Trae bolsas|Ven temprano]",
    ["theres a list up at the methodist church. people nobody can find. [go look|i looked. go look]"] = "hay una lista en la iglesia metodista. gente q nadie encuentra. [ve a ver|yo ya vi. ve a ver]",
    ["A deputy came by asking about the [Millers|Hendersons|Parkers]. Wrote something down and left"] = "Vino un alguacil preguntando por los [Miller|Henderson|Parker]. Anotó algo y se fue",
    ["Lois says [seven|nine] families won't answer their doors. She's scared. [So am I|We should help]"] = "Lois dice que [siete|nueve] familias no abren la puerta. Tiene miedo. [Yo también|Deberíamos ayudar]",
    ["The list at the church got longer today. Lois added [three|four] names after lunch"] = "La lista de la iglesia creció hoy. Lois agregó [tres|cuatro] nombres después de comer",
    ["soldiers at the old bunker gate. wouldnt say why. [just stood there|turned us around]"] = "soldados en la reja del viejo búnker. no quisieron decir por q. [ahí parados nada más|nos regresaron]",
    ["Landlines are down across the county. Knox Mobile's still up. Use the cell"] = "Los teléfonos fijos no funcionan en todo el condado. Knox Mobile sigue funcionando. Usen el celular",
    ["All circuits are busy every time I call your mother. Texts go through. Keep yours on"] = "Todos los circuitos ocupados cada vez que llamo a tu mamá. Los mensajes sí llegan. Deja el tuyo prendido",
    ["Called the phone company. Dot answered. She sounded [so tired|hoarse]. Been there since [yesterday|Tuesday]"] = "Llamé a la telefónica. Contestó Dot. Se oía [muy cansada|ronca]. Está ahí desde [ayer|el martes]",
    ["one bar [at the window|by the chimney]. texts go through after [3|4] tries. calls never"] = "una rayita [en la ventana|junto a la chimenea]. los mensajes pasan después de [3|4] intentos. las llamadas nunca",
    ["Louisville office isn't answering. The test phones are the only ones still activating. [Don't ask me why|Ray says wait]"] = "La oficina de Louisville no contesta. Los teléfonos de prueba son los únicos que todavía se activan. [No me preguntes por qué|Ray dice que esperemos]",
    ["watch channel 3. theyre saying people are biting people in louisville. [at the hospital|downtown]"] = "pon el canal 3. dicen q la gente está mordiendo gente en louisville. [en el hospital|en el centro]",
    ["Come home [right now|before dark]. The news says lock your doors. Your father's getting gas"] = "Ven a casa [ahora mismo|antes de oscurecer]. Las noticias dicen que cierres con llave. Tu papá fue por gasolina",
    ["fireworks cancelled. [army trucks|cops] blocking the bridge. everybody's leaving and nobody knows why"] = "cancelaron los fuegos. [camiones del ejército|policías] bloqueando el puente. todos se están yendo y nadie sabe por q",
    ["saw [smoke|lights] toward the [plant|base]. [explosions|gunshots] maybe. dont tell ur parents"] = "vi [humo|luces] por [la planta|la base]. [explosiones|disparos] tal vez. no les digas a tus papás",
    ["News says the Louisville ER is full. Don't open the door for anybody. [Kids are inside|I locked the gate]"] = "Las noticias dicen que urgencias de Louisville está lleno. No le abras a nadie. [Los niños están adentro|Cerré la reja con llave]",
    ["The IGA is out of formula. Try the gas station. Or the Kroger on Dixie"] = "El IGA ya no tiene fórmula. Intenta en la gasolinera. O en el Kroger de Dixie",
    ["All circuits busy. Can't reach the [daycare|camp]. Text me the second you hear anything"] = "Todos los circuitos ocupados. No logro comunicarme con [la guardería|el campamento]. Escríbeme en cuanto sepas algo",
    ["Kids have been in the basement since 8. Sirens outside. [We're playing go fish|They think it's a storm drill]"] = "Los niños están en el sótano desde las 8. Sirenas afuera. [Estamos jugando a las cartas|Creen que es un simulacro de tormenta]",
    ["All hands to the hospital by 0500. Wear what you've got. Triage at the side door"] = "Todo el personal al hospital antes de las 0500. Vengan con lo que tengan puesto. Triaje en la puerta lateral",
    ["The church needs cooks for the shelter kitchen. If you can't work, go there. They'll feed you"] = "La iglesia necesita cocineros para la cocina del refugio. Si no puedes trabajar, ve para allá. Te van a dar de comer",
    ["Staying open all night for the checkpoint crews. Grill only. Tips split at shift end"] = "Abrimos toda la noche para la gente de los retenes. Solo parrilla. Las propinas se reparten al final del turno",
    ["my [cousin|roommate] works at the hospital. says its bad. she wont come home"] = "mi [prima|compañera de cuarto] trabaja en el hospital. dice q está feo. no quiere venir a casa",
    ["Store's cleaned out. No water, no bread. I'm filling the tub now"] = "Vaciaron la tienda. No hay agua, no hay pan. Estoy llenando la tina",
    ["Power flickered downtown. I've got candles out. [The kids think it's fun|Hurry home]"] = "La luz parpadeó en el centro. Saqué velas. [A los niños les parece divertido|Apúrate a llegar]",
    ["dad says the plant locked the gates. he's stuck inside. [dont panic|come to moms]"] = "papá dice q la planta cerró las rejas. está atrapado adentro. [no te asustes|vente a casa de mamá]",
    ["the church is open to everybody. mom wants us there. wedding's [off|postponed] obviously"] = "la iglesia está abierta para todos. mamá quiere q vayamos. la boda [se canceló|se pospuso] obvio",
    ["IGA's cleaned out. i grabbed [two cases of water|what i could]. come to my place"] = "vaciaron el IGA. agarré [dos cajas de agua|lo q pude]. vente a mi casa",
    ["Channel 3 says the hospital downtown is locked down. [Call me|Text me back] right now"] = "En el canal 3 dicen que cerraron el hospital del centro. [Llámame|Contéstame] ahora mismo",
    ["somebody got bit at the kroger on dixie. cops everywhere. [dont go|stay inside]"] = "mordieron a alguien en el kroger de dixie. policías por todos lados. [no vayas|quédate adentro]",
    ["All units to the bridges. The Guard is taking over downtown. Report to {jobPlace}"] = "Todas las unidades a los puentes. La Guardia está tomando el centro. Preséntense en {jobPlace}",
    ["The mayor's on TV at [noon|6]. They're saying curfew. Fill the tub while the water's on"] = "El alcalde sale en la tele a las [12|6]. Dicen que habrá toque de queda. Llena la tina mientras haya agua",
    ["amusement park's closed. fence going up. sirens nonstop by broadway"] = "cerraron el parque de diversiones. están poniendo una cerca. sirenas sin parar por broadway",
    ["Tony can't get to the hospital. Abandoned cars on [9th|3rd]. He's [turning back|staying at the shop]"] = "Tony no puede llegar al hospital. Autos abandonados en la [9|3]. [Se va a regresar|Se queda en el local]",
    ["pondview is out of water and bleach. truck didnt come. fill your tubs tonight"] = "en el pondview ya no hay agua ni cloro. no llegó el camión. llenen las tinas hoy",
    ["heard [gunshots|screaming] down by the ferry dock around 2am. anybody else"] = "se oyeron [disparos|gritos] por el muelle del ferry como a las 2am. alguien más",
    ["Closing at 6. No deliveries, the trucks are stopped at the county line. Don't come in"] = "Cerramos a las 6. No hay entregas, los camiones están detenidos en la línea del condado. No vengas",
    ["The board's been lit up since 4 this morning. Everybody's calling Louisville. Come in if you can, hon"] = "El conmutador no ha parado desde las 4 de la mañana. Todos están llamando a Louisville. Ven si puedes, cariño",
    ["Management says keep the board staffed through Sunday. Double time. Bring a bag and your good shoes"] = "La gerencia dice que el conmutador tiene que estar atendido hasta el domingo. Pago doble. Trae una maleta y tus zapatos buenos",
    ["The news says Louisville closed its schools. Our principal hasn't said a word"] = "Las noticias dicen que Louisville cerró sus escuelas. Nuestro director no ha dicho nada",
    ["The school opens as a shelter tomorrow. We need cots and blankets at {jobPlace} by noon"] = "La escuela abre como refugio mañana. Necesitamos catres y cobijas en {jobPlace} antes del mediodía",
    ["The janitor has every key and won't leave the building. The principal yelled at him. He just locked the office"] = "El conserje tiene todas las llaves y no quiere salir del edificio. El director le gritó. Él nada más cerró la oficina con llave",
    ["The school shelter was full by 6. They turned people away at the gate"] = "El refugio de la escuela estaba lleno a las 6. Regresaron a la gente en la reja",
    ["Power flickered at {jobPlace}. The freezer held. Boss says lock up if it drops again"] = "La luz parpadeó en {jobPlace}. El congelador aguantó. El jefe dice que cerremos si se vuelve a ir",
    ["Marcus says don't believe the radio. It's not what it looks like. That's all he'd say"] = "Marcus dice que no le creas a la radio. No es lo que parece. Es todo lo que quiso decir",
    ["Danny's unit got moved to the line. He texted we're holding. I turned the news off"] = "Movieron a la unidad de Danny a la línea. Escribió aguantamos. Apagué las noticias",
    ["dad said they brought the sick inside the wire. delete this. hes scared and he never gets scared"] = "papá dijo q metieron a los enfermos dentro del alambrado. borra esto. tiene miedo y él nunca tiene miedo",
    ["flares over the base all night. you can see them from my window. the dogs wont stop"] = "bengalas sobre la base toda la noche. se ven desde mi ventana. los perros no paran",
    ["Marcus's CO came by the house for his spare gear. Wouldn't look me in the eye"] = "El oficial de Marcus vino a la casa por su equipo de repuesto. No me miraba a los ojos",
    ["Channel 3 says animals are acting strange in Louisville. Keep yours inside"] = "En el canal 3 dicen que los animales se portan raro en Louisville. Mantén los tuyos adentro",
    ["the shelter at the school wont take pets. people are leaving dogs tied to the fence"] = "el refugio de la escuela no acepta mascotas. la gente está dejando perros amarrados a la cerca",
    ["Channel 3 says the Louisville ERs are turning people away. Some kind of virus. They won't name it"] = "En el canal 3 dicen que las urgencias de Louisville están rechazando gente. Algún tipo de virus. No le dicen el nombre",
    ["Somebody at the feed store swears it was a chemical spill at [the plant|the base]. Nobody official is saying anything"] = "Alguien en la tienda de forraje jura que fue un derrame químico en [la planta|la base]. Nadie oficial dice nada",
    ["the tv guy said [a new rabies|a mutated flu]. spreads by biting. [turn it off|change the channel]"] = "el de la tele dijo [una rabia nueva|una gripe mutada]. se contagia por mordida. [apágala|cambia el canal]",
    ["A preacher on the radio says it's judgment on the land. Your mother cried. I turned it off"] = "Un predicador en la radio dice que es el juicio sobre la tierra. Tu mamá lloró. La apagué",
    ["the news lady stopped in the middle of a sentence. dead air. then the emergency tone. did u see it"] = "la de las noticias se calló a media frase. silencio. luego el tono de emergencia. lo viste",
    ["A doctor on channel 3 said don't come to the ER. We can't help you. Her voice broke on the last part"] = "Una doctora en el canal 3 dijo no vengan a urgencias. No podemos ayudarlos. Se le quebró la voz al final",
    ["The radio says the Guard is moving down 31W. They're calling it a quarantine zone. Nobody in or out"] = "La radio dice que la Guardia viene bajando por la 31W. Le dicen zona de cuarentena. Nadie entra ni sale",
    ["Our supplier in Louisville says the warehouses are sealed. Government order. We're on our own"] = "Nuestro proveedor de Louisville dice que sellaron las bodegas. Orden del gobierno. Estamos solos",
    ["News helicopter over the river. The reporter said there are people in the water. Then they cut away"] = "Un helicóptero de las noticias sobre el río. El reportero dijo que hay gente en el agua. Luego cortaron",
    ["Earl says there were green clouds over the base last night. Something blew. The wind's coming our way"] = "Earl dice que anoche hubo nubes verdes sobre la base. Algo explotó. El viento viene para acá",
    ["The governor's on at 8. They're saying emergency powers. Fill every container we have"] = "El gobernador sale a las 8. Hablan de poderes de emergencia. Llena todos los recipientes que tengamos",
    ["The church opened its doors to everybody. Cots in the fellowship hall. Your father went to help"] = "La iglesia abrió sus puertas a todos. Catres en el salón comunitario. Tu papá fue a ayudar",
    ["the prayer chain blew up. [30|40] names since noon. they're reading them out before dark"] = "la cadena de oración explotó. [30|40] nombres desde el mediodía. los van a leer antes de oscurecer",
    ["grandmas church group is making sandwiches for the shelter. no bread anywhere. they need peanut butter"] = "el grupo de la iglesia de la abuela está haciendo sándwiches para el refugio. no hay pan en ningún lado. necesitan mantequilla de maní",
    ["Earl's CB went quiet after 2am. The last thing he said was Psalm 91. Static since"] = "El CB de Earl se calló después de las 2am. Lo último que dijo fue el Salmo 91. Estática desde entonces",
    ["Wednesday supper is cancelled. The kitchen's cooking for the shelter. Come help at 4 if you can"] = "Se cancela la cena del miércoles. La cocina está cocinando para el refugio. Ven a ayudar a las 4 si puedes",
    ["news says louisville hospitals are turning people away. is our date still on?"] = "las noticias dicen q los hospitales de louisville están rechazando gente. sigue en pie nuestra cita?",
    ["saw {partner} at the kroger with somebody. didnt see her face. they grabbed water and left"] = "vi a {partner} en el kroger con alguien. no le vi la cara a ella. agarraron agua y se fueron",
    ["{partner} called the house [twice|three times] looking for you. Call them back"] = "{partner} llamó a la casa [dos|tres] veces buscándote. Devuélvele la llamada",
    ["fireworks [ended early|got called off]. [sirens|gunshots] over the music. [get home|stay inside]"] = "los fuegos [terminaron temprano|se cancelaron]. [sirenas|disparos] por encima de la música. [vete a casa|quédate adentro]",
    ["Dot at the phone company says the lines lit up all night. [Text, don't call|Calls won't go through]"] = "Dot de la telefónica dice que las líneas no pararon en toda la noche. [Escribe, no llames|Las llamadas no entran]",
    ["trish says dont come to the ER [no matter what|for anything]. [shes sleeping there|double shift again]"] = "trish dice q no vengas a urgencias [pase lo q pase|por nada]. [está durmiendo ahí|otra vez turno doble]",
    ["[ran into|talked to] a soldier at the gas station. [he wouldnt say anything|he said go home]. trucks all over 31W"] = "[me encontré con|hablé con] un soldado en la gasolinera. [no quiso decir nada|dijo vete a casa]. camiones por toda la 31W",
    ["the party at west maple [broke up|cleared out] early. [somebody got sick|a man collapsed] on the patio"] = "la fiesta de west maple [se acabó|se vació] temprano. [alguien se enfermó|un señor se desplomó] en el patio",

    -- their last day (the owner's own texts) -------------------------------------------------------------------
    ["[going out|heading to] the [pharmacy|igA] for medicine. if i dont 6 dont come"] = "[salgo a|voy a] [la farmacia|el iga] por medicina. si no a las 6 no vengan",
    ["[fever|temp] [broke|dropped] at 3 am. sweat soaked the sheets. feel cold now"] = "[la fiebre|la temperatura] [cedió|bajó] a las 3 am. empapé las sábanas de sudor. ahora tengo frío",
    ["got the [keys|cash] from the [coffee can|top shelf]. tank's full. leaving tonight. dont wake anyone"] = "saqué [las llaves|el efectivo] [de la lata de café|del estante de arriba]. tanque lleno. me voy esta noche. no despiertes a nadie",
    ["hid the [receipt|box] in the [dryer|vent|toolbox]. hank called ready. paid cash"] = "escondí [el recibo|la caja] en [la secadora|la rejilla|la caja de herramientas]. hank llamó, ya está. pagué en efectivo",
    ["told [partner|mom] [im|i'm] working late. really meeting lonnie at the truck stop"] = "le dije a [mi pareja|mamá] q [salgo|voy a salir] tarde del trabajo. en realidad voy a ver a lonnie en la parada de camiones",
    ["[wrote|left] the [note|list] in the cookbook. water under the sink. for them"] = "[escribí|dejé] [la nota|la lista] en el libro de recetas. agua bajo el fregadero. para ellos",
    ["the [collection|repo] [call|letter] came today. 30 days. sold the watch. nobody knows"] = "hoy llegó [la llamada|la carta] de [cobranza|embargo]. 30 días. vendí el reloj. nadie sabe",
    ["locked the [bedroom|basement] door from [outside|inside]. he stopped moaning an hour ago. sit with him"] = "cerré la puerta [del cuarto|del sótano] con llave por [fuera|dentro]. dejó de quejarse hace una hora. me quedo con él",
    ["[kayla|bobby] [texted|called] scared. turned back at the fence. told her im fine. lied"] = "[kayla|bobby] [escribió|llamó] con miedo. se tuvo q regresar en la cerca. le dije q estoy bien. mentí",
    ["[going to look for water|going out for medicine]. if i dont text by 6 dont come looking"] = "[voy a buscar agua|salgo por medicina]. si no escribo antes de las 6 no vengan a buscarme",
    ["the scratch is nothing. [dont tell mom|dont tell the kids]"] = "el rasguño no es nada. [no le digas a mamá|no les digas a los niños]",
    ["im going to sit with [him|her] a while. [its quiet here|the door is locked]"] = "me voy a quedar con [él|ella] un rato. [aquí está tranquilo|la puerta tiene llave]",
    ["[heading to the IGA|going for the truck]. back before dark"] = "[voy al IGA|voy por la camioneta]. vuelvo antes de oscurecer",
    ["dont wait up. [checking on the neighbor|gonna see about the generator]"] = "no me esperen despiertos. [voy a ver al vecino|voy a revisar el generador]",
    ["bike chain snapped. walking home from [31W|the lumberyard]. its fine"] = "se rompió la cadena de la bici. camino a casa desde [la 31W|el aserradero]. todo bien",
    ["Took my pills. Sitting on the porch watching the road"] = "Me tomé las pastillas. Aquí en el porche viendo el camino",
    ["travis didnt show. going to his place [the back way|by the river road]"] = "travis no llegó. voy a su casa [por atrás|por el camino del río]",
    ["dog wont stop barking at [the basement door|the back fence]. probably a raccoon"] = "el perro no deja de ladrarle a [la puerta del sótano|la cerca de atrás]. seguro es un mapache",
    ["ambulance never came. driving her myself. [taking the back roads|dont call]"] = "la ambulancia nunca llegó. la llevo yo en el auto. [voy por los caminos de atrás|no llamen]",
    ["chained the gate. keep the kids inside [no matter what|till i get back]"] = "le puse cadena a la reja. dejen a los niños adentro [pase lo q pase|hasta q vuelva]",
    ["The pastor came by and prayed with me. Said the church is full. I'm all right here"] = "Vino el pastor y rezó conmigo. Dijo que la iglesia está llena. Aquí estoy bien",
    ["nailed boards over the [bedroom|kitchen] window. [told the kids its a game|kids are asleep]"] = "clavé tablas en la ventana [del cuarto|de la cocina]. [les dije a los niños q es un juego|los niños están dormidos]",
    ["I wrote the grandkids' names in the family Bible. [Just in case|So they know]"] = "Escribí los nombres de los nietos en la Biblia de la familia. [Por si acaso|Para que sepan]",
    ["nobody came to relieve me. been here [16 hours|since 6 this morning]. still here"] = "nadie vino a relevarme. llevo aquí [16 horas|desde las 6 de la mañana]. sigo aquí",
    ["told the kids we're camping. [they believed me|the little one didnt]"] = "les dije a los niños q estamos acampando. [me creyeron|el chiquito no]",
    ["the siren started again. [lost count today|i stopped counting]"] = "empezó la sirena otra vez. [hoy perdí la cuenta|ya dejé de contar]",
    ["going down to the [cellar|barn] to check the stores. be right back"] = "voy [al sótano|al granero] a revisar las provisiones. ahorita vuelvo",
    ["[made it to|im at] {jobPlace}. door's locked from the inside. ill wait here"] = "[llegué a|estoy en] {jobPlace}. la puerta tiene llave por dentro. aquí espero",
    ["tell {mom} i love her. [i didnt say it enough|tell her im sorry about easter]"] = "dile a {mom} q la quiero. [no se lo dije suficiente|dile q perdón por lo de pascua]",
    ["the kids are at [my sisters|grandmas]. if anybody asks thats where they are. [dont come here|stay there]"] = "los niños están [con mi hermana|con la abuela]. si alguien pregunta ahí están. [no vengan aquí|quédense allá]",
    ["battery's [almost gone|on one bar]. [the radio says|they keep saying] stay inside. so im staying inside"] = "la batería [ya casi se acaba|está en una rayita]. [la radio dice|siguen diciendo] q no salgamos. así q no salgo",
    ["[cant stop shaking|so cold]. its july and im under 2 blankets. probably nothing"] = "[no paro de temblar|mucho frío]. es julio y estoy bajo 2 cobijas. seguro no es nada",
    ["if u see my car at the [IGA|lumberyard] dont stop. just keep going ok"] = "si ves mi auto en [el IGA|el aserradero] no te pares. sigue de largo ok",
    ["left the dog [with the neighbors|at the church]. [her name is Daisy|she likes the porch]"] = "dejé a la perra [con los vecinos|en la iglesia]. [se llama Daisy|le gusta el porche]",
    ["the spare key is [in the coffee can|under the gnome]. [take what you need|everything in the pantry is yours]"] = "la llave de repuesto está [en la lata de café|bajo el enanito]. [llévate lo q necesites|todo lo de la alacena es tuyo]",
    ["somebody keeps trying the back door. [i turned the lights off|im in the bathroom]. text dont call"] = "alguien sigue intentando abrir la puerta de atrás. [apagué las luces|estoy en el baño]. escribe no llames",
    ["I fed the cat and locked up. I'm going to sit on the porch a while. It's a pretty evening"] = "Le di de comer al gato y cerré con llave. Me voy a sentar un rato en el porche. Está bonita la tarde",
    ["[still here|on shift]. we stopped counting. [dont wait up|kiss the kids for me]"] = "[sigo aquí|de turno]. ya dejamos de contar. [no me esperes|dales un beso a los niños de mi parte]",
    ["i wrapped it real tight. its fine. [just tired|gonna lie down a minute]"] = "lo vendé bien apretado. está bien. [solo cansancio|me voy a acostar un minuto]",
    ["[found|got] a ride with some guys from the plant. theyre going [south|to the river]. ill text when i can"] = "[encontré|conseguí] q me llevaran unos de la planta. van [al sur|al río]. escribo cuando pueda",
    ["[sorry about|forget about] the fight. it was stupid. [none of it matters|i was wrong]"] = "[perdón por|olvida] la pelea. fue una tontería. [nada de eso importa|me equivoqué]",
    ["{partner} if you get this, [the money's in the freezer|the papers are in the safe]. [I love you|Take care of them]"] = "{partner} si te llega esto, [el dinero está en el congelador|los papeles están en la caja fuerte]. [Te amo|Cuídalos]",
    ["[taking|driving] the back way to the [pondview|IGA]. [car's|tank's] almost empty. wish me luck"] = "[voy|manejo] por atrás hasta [el pondview|el IGA]. [el auto ya casi no tiene gasolina|el tanque está casi vacío]. deséame suerte",

    -- after they died ------------------------------------------------------------------------------------------
    ["{first} please. [Just one word|Just say ok]"] = "{first} por favor. [Solo una palabra|Solo di ok]",
    ["[came by|knocked] your place. door was open. [where did u go|call me]"] = "[pasé por|toqué en] tu casa. la puerta estaba abierta. [a dónde fuiste|llámame]",
    ["[I kept dinner warm|I left the porch light on]. I know. I'm leaving it on anyway"] = "[Te guardé la cena caliente|Dejé la luz del porche encendida]. Ya sé. De todos modos la dejo",
    ["{first} you are listed missing. [Answer if you can|Radio in if you can]"] = "{first}, figuras en la lista de desaparecidos. [Contesta si puedes|Repórtate por radio si puedes]",
    ["The truck's fixed. Keys are on the hook. Come get it whenever. Love, Dad"] = "Ya arreglé la camioneta. Las llaves están en el gancho. Ven por ella cuando quieras. Te quiere, Papá",
    ["The church ladies asked about you. I said you're [busy|working]. Call me please"] = "Las señoras de la iglesia preguntaron por ti. Les dije que [tienes mucho que hacer|estás trabajando]. Llámame por favor",
    ["moms freaking out. she made [3 pans of brownies|your bed twice]. just text back"] = "mamá está histérica. hizo [3 charolas de brownies|tu cama dos veces]. solo contesta",
    ["The kids keep asking. I told them you're at work. [Please come home|Don't make me a liar]"] = "Los niños siguen preguntando. Les dije que estás en el trabajo. [Por favor ven a casa|No me hagas quedar mal]",
    ["[bobby|travis] came by looking for you. didnt say why. hit me up"] = "[bobby|travis] vino a buscarte. no dijo por q. escríbeme",
    ["{first}, we need you [tomorrow|Saturday]. Half the crew's out. Text back if you're coming"] = "{first}, te necesitamos [mañana|el sábado]. Falta la mitad del personal. Contesta si vas a venir",
    ["Your [car payment|insurance bill] came. I put it by the phone. Let me know you got it"] = "Llegó [el pago del auto|la cuenta del seguro]. La dejé junto al teléfono. Avísame que la viste",
    ["Heard gunshots by [the river|the plant] last night. Don't go looking. Your mother's worried sick"] = "Anoche se oyeron disparos por [el río|la planta]. No vayas a ver. Tu mamá está con el alma en un hilo",
    ["Power flickered [twice|three times]. Lanterns are out. Come home please"] = "La luz parpadeó [dos|tres] veces. Ya saqué las lámparas. Ven a casa por favor",
    ["{first}, you're on the board for tonight. Confirm by radio. [Now|Please]"] = "{first}, estás en el tablero para esta noche. Confirma por radio. [Ya|Por favor]",
    ["Your name's on the prayer chain. I told them you're fine. Please call so I'm not lying to church people"] = "Tu nombre está en la cadena de oración. Les dije que estás bien. Por favor llama para no estar mintiéndole a la gente de la iglesia",
    ["found your keys on the porch. screen door was open. [where are you|this isnt funny]"] = "encontré tus llaves en el porche. la puerta de malla estaba abierta. [dónde estás|esto no es gracioso]",
    ["The baby's fever broke. [I need you here|We need you]. I need you to see her"] = "Al bebé se le quitó la fiebre. [Te necesito aquí|Te necesitamos]. Necesito que la veas",
    ["Grandma fell [yesterday|Tuesday]. She keeps asking for you. [Just call her|Call her please]"] = "La abuela se cayó [ayer|el martes]. No deja de preguntar por ti. [Solo llámala|Llámala por favor]",
    ["the guard set up at the [school|fairgrounds]. they took our names and asked where u live. [i didnt know what to say|i said here]"] = "la guardia se instaló en [la escuela|la feria]. anotaron nuestros nombres y preguntaron dónde vives. [no supe q decir|dije q aquí]",
    ["I packed the car. We're going to {hometown}. [Come find us|I'll wait as long as I can]"] = "Ya cargué el auto. Nos vamos a {hometown}. [Ven a buscarnos|Voy a esperar todo lo que pueda]",
    ["The siren at the plant went off at 3am. Ran an hour. Your mother didn't sleep. Neither did I"] = "La sirena de la planta sonó a las 3am. Una hora entera. Tu mamá no durmió. Yo tampoco",
    ["The dog won't stop staring at the back door. Deadbolt's thrown. Text me so I know you're ok"] = "El perro no deja de mirar la puerta de atrás. Le puse el cerrojo. Escríbeme para saber que estás bien",
    ["rev lois is writing down names of people who didnt come home. ur not on it. [dont be|call]"] = "la rev lois está anotando los nombres de la gente q no volvió a casa. no estás en la lista. [q no te pongan|llama]",
    ["The [cherry|apple] pie is cooling. I saved you a slice. Just come home. Love, Mom"] = "El pastel de [cereza|manzana] se está enfriando. Te guardé una rebanada. Solo ven a casa. Te quiere, Mamá",
    ["I made [your favorite|the potato salad] in case you come. Your plate's in the fridge"] = "Hice [tu comida favorita|la ensalada de papa] por si vienes. Tu plato está en el refri",
    ["dude [ur mom|ur sister] keeps calling me. text her back. [seriously|please]"] = "oye [tu mamá|tu hermana] no deja de llamarme. contéstale. [en serio|por favor]",
    ["Drove by your place. [Car's there|Lights are off]. Knocked. I'll try again tomorrow"] = "Pasé por tu casa. [Tu auto está ahí|Las luces están apagadas]. Toqué. Mañana lo intento otra vez",
    ["[i'm not mad anymore|forget the money]. just answer"] = "[ya se me pasó el enojo|olvida el dinero]. solo contesta",
    ["[I'm at the church|We're at the school] if you're looking for us. They have a list. Your name's on it"] = "[Estoy en la iglesia|Estamos en la escuela] si nos buscas. Tienen una lista. Tu nombre está ahí",
    ["Someone said they saw you at the [gas station|IGA]. Was it you? Just say yes or no"] = "Alguien dijo que te vio en [la gasolinera|el IGA]. ¿Eras tú? Solo di sí o no",
    ["[your truck's|your bike's] still out front. i'm leaving it there. u'll want it"] = "[tu camioneta sigue|tu bici sigue] afuera. ahí la dejo. la vas a querer",
    ["{first} you missed [two|three] shifts. Not mad. Just let me know you're ok"] = "{first} faltaste a [dos|tres] turnos. No es regaño. Solo avísame que estás bien",
    ["Your mother wants you to know she's [praying|keeping a candle lit]. So am I. Call"] = "Tu mamá quiere que sepas que [está rezando|tiene una vela encendida]. Yo también. Llama",
    ["i fed [ur fish|the cat]. its fine. i'll keep doing it. [come home|text me]"] = "le di de comer a [tus peces|el gato]. todo bien. lo voy a seguir haciendo. [ven a casa|escríbeme]",
    ["The baby said [dada|mama] today. I wanted you to know"] = "Hoy el bebé dijo [papá|mamá]. Quería que lo supieras",
    ["[going to the river|heading to the school] tonight with everybody. [we'll wait for u|left a note on ur door]"] = "[vamos al río|vamos a la escuela] esta noche con todos. [te vamos a esperar|te dejé una nota en la puerta]",
    ["Happy birthday sweetheart. I didn't forget. [I won't forget|I'll keep the cake]"] = "Feliz cumpleaños, corazón. No se me olvidó. [No se me va a olvidar|Te guardo el pastel]",
    ["Paycheck is in the office if you want it. [Door's unlocked|The manager has it]"] = "Tu cheque está en la oficina si lo quieres. [La puerta está abierta|Lo tiene el gerente]",
    ["{first}, [call your mother|answer your mother]. She's [beside herself|not sleeping]"] = "{first}, [llama a tu mamá|contéstale a tu mamá]. [Está desesperada|No duerme]",
    ["The kids keep asking when you're coming home. [I don't know what to say|I said soon]"] = "Los niños siguen preguntando cuándo vas a volver. [No sé qué decirles|Les dije que pronto]",
    ["{first}, [payroll|the office] needs your hours. [Call when you can|Is everything ok?]"] = "{first}, [nómina|la oficina] necesita tus horas. [Llama cuando puedas|¿Todo bien?]",
}
